#define KOTATSU_ANNOTATE_IMPL(tag, ...)                                                                KOTATSU_ANNOTATION(tag, __VA_ARGS__);                                                              typename ::kotatsu::meta::annotate<tag>::template type
#define KOTATSU_ANNOTATE(...)                                                                          KOTATSU_ANNOTATE_IMPL(KOTATSU_CONCAT(kotatsu_annotation_, __LINE__), __VA_ARGS__)
